import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:onegame/core/time/regions.dart';
import 'package:onegame/data/daily/daily_logic.dart';
import 'package:onegame/data/daily/streak.dart';

/// The local backend must reproduce the server's logic exactly
/// (vectors generated by `npm run gen:daily-vectors`).
void main() {
  final vectors = jsonDecode(
    File('../shared/daily_vectors.json').readAsStringSync(),
  ) as Map<String, dynamic>;

  test('local schedule = TypeScript schedule', () {
    final expected = vectors['schedule'] as List<dynamic>;
    final first = (expected.first as Map<String, dynamic>)['dayKey'] as String;
    final last = (expected.last as Map<String, dynamic>)['dayKey'] as String;
    final ours = localSchedule(first, last);
    expect(ours.length, expected.length);
    for (var i = 0; i < ours.length; i++) {
      final e = expected[i] as Map<String, dynamic>;
      final d = ours[i];
      expect(d.dayKey, e['dayKey']);
      expect(d.gameId, e['gameId'], reason: d.dayKey);
      expect(d.seed, e['seed'], reason: d.dayKey);
      expect(d.modifierId, e['modifierId'], reason: d.dayKey);
      final alerts = e['alertAt'] as Map<String, dynamic>;
      for (final r in Region.values) {
        expect(
          d.alertAt[r]!.millisecondsSinceEpoch,
          alerts[r.name],
          reason: '${d.dayKey} ${r.name}',
        );
      }
    }
  });

  test('streak & joker = TypeScript', () {
    for (final sc in vectors['streaks'] as List<dynamic>) {
      final m = sc as Map<String, dynamic>;
      var s = const StreakState();
      final ops = m['ops'] as List<dynamic>;
      final states = m['states'] as List<dynamic>;
      for (var i = 0; i < ops.length; i++) {
        final op = ops[i] as List<dynamic>;
        if (op[0] == 'play') {
          s = recordPlay(s, op[1] as String, op[2] as bool);
        } else if (jokerCase(s, op[1] as String) != null) {
          s = useJoker(s, op[1] as String);
        }
        expect(s.toJson(), states[i], reason: '$ops step $i');
      }
    }
  });

  test('regions from time zones', () {
    expect(regionForTimeZone('Europe/Paris', Duration.zero), Region.europe);
    expect(regionForTimeZone('Africa/Dakar', Duration.zero), Region.europe);
    expect(
      regionForTimeZone('America/Chicago', const Duration(hours: -6)),
      Region.americas,
    );
    expect(
      regionForTimeZone('America/Sao_Paulo', const Duration(hours: -3)),
      Region.americas,
    );
    expect(
      regionForTimeZone('America/Denver', const Duration(hours: -7)),
      Region.west,
    );
    expect(
      regionForTimeZone('Asia/Kolkata', const Duration(hours: 5, minutes: 30)),
      Region.asia,
    );
    expect(
      regionForTimeZone('Australia/Sydney', const Duration(hours: 11)),
      Region.asia,
    );
    expect(
      regionForTimeZone('Etc/GMT-3', const Duration(hours: 3)),
      Region.europe,
    );
    expect(
      dayKeyFor(DateTime.utc(2026, 11, 24, 23, 30), Region.europe),
      '2026-11-25',
    );
    expect(
      dayKeyFor(DateTime.utc(2026, 11, 24, 23, 30), Region.west),
      '2026-11-24',
    );
    expect(dayOfWeek('2026-11-29'), 0);
  });
}
